pub fn discover(slots: &mut [Slot], cid: u64, txid: u32, now: u64) -> Option<usize> {
    let mut first_offered: Option<usize> = None;
    let mut i: usize = 0;
    while i < slots.len() {
        let s = slots[i];
        let usable = match s.kind {
            Kind::Offered => {
                if s.id != cid {
                    first_offered = Some(i);
                    false
                } else {
                    true
                }
            }
            // (explicit ifs: the same, and Bool results Aeneas types right)
            Kind::Assigned => {
                if s.id == cid {
                    true
                } else if now >= s.lease_end {
                    true
                } else {
                    false
                }
            }
            Kind::Free => true,
        };
        if usable {
            slots[i] = Slot { kind: Kind::Offered, id: cid, txid, lease_end: s.lease_end };
            return Some(i);
        }
        i += 1;
    }
    match first_offered {
        Some(j) => {
            let le = slots[j].lease_end;
            slots[j] = Slot { kind: Kind::Offered, id: cid, txid, lease_end: le };
            Some(j)
        }
        None => None,
    }
}

