pub fn request(slots: &mut [Slot], cid: u64, txid: u32, now: u64, new_end: u64) -> Option<usize> {
    let mut i: usize = 0;
    while i < slots.len() {
        let s = slots[i];
        let hit = match s.kind {
            Kind::Offered => {
                if s.id == cid && s.txid == txid {
                    true
                } else {
                    false
                }
            }
            Kind::Assigned => {
                if s.id == cid && s.txid == txid && now < s.lease_end {
                    true
                } else {
                    false
                }
            }
            Kind::Free => false,
        };
        if hit {
            slots[i] = Slot { kind: Kind::Assigned, id: cid, txid, lease_end: new_end };
            return Some(i);
        }
        i += 1;
    }
    None
}

